// ***************
// Filename: object_tracker_top.sv
// Author: FPGA Cores 4 U
// Description: object_tracker with its AXI4-Lite register interface, the
//   block designs and testbenches instantiate: the register map
//   object_tracker_regs (u_regs, src/include/object_tracker_regs.sv, ID
//   "OTRK", VERSION and DATE at 0x00-0x08, the registers from 0x10) and the
//   logic object_tracker (u_core, src/object_tracker.sv), joined by the
//   register interface object_tracker_regs_if (u_regs_if). Generated by
//   ip/scripts/regmap_gen.py from object_tracker_regs.json and the ports of
//   object_tracker: regenerate after changing either. Clock - clk. Reset -
//   synchronous active low rst_n.
// Date: 2026-10-21
module object_tracker_top #(
  parameter int CW = 16,
  parameter int NBLOB = 8
) (
  input  logic clk,
  input  logic rst_n,
  // s_axil: axil_if.slave (ip/shared/src/interfaces/axil_if.sv), ADDR_W = 9
  axil_if.slave s_axil,
  // s_axis: axis_if.monitor (ip/shared/src/interfaces/axis_if.sv), DATA_W = 24
  axis_if.monitor s_axis,
  input  logic [1:0] feat_i,
  output logic done_o
);
  // register interface between the register map and the logic
  object_tracker_regs_if u_regs_if ();

  object_tracker_regs u_regs (
    .clk,
    .rst_n,
    .s_axil(s_axil),
    .r(u_regs_if)
  );
  object_tracker #(
    .CW(CW),
    .NBLOB(NBLOB)
  ) u_core (
    .clk,
    .rst_n,
    .s_axis,
    .feat_i,
    .done_o,
    .regs(u_regs_if)
  );
endmodule
